command:
// Lonien — Cura de Emergência: cura 4d8+4 PV agora no herói selecionado (1x por cena).
// A cura automática ao cair a 0 PV já vem do módulo Coração de Rubi; esta macro é para usar na hora.
actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) return ui.notifications.warn("Selecione o token do herói que Lonien está ajudando.");
const api = game.modules.get("giriarpg-coracao-de-rubi")?.api;
if (!api) return ui.notifications.warn("Ative o módulo Coração de Rubi.");
await api.curaLonien(actor);
